llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Niraparib has an absolute oral bioavailability of approximately 73% in humans after a 300 mg single dose, directly demonstrating high F for a basic heteroaromatic amine-containing drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Flecainide shows 90-95% absolute oral bioavailability in healthy subjects, supporting high F for a lipophilic basic amine with aromatic and heteroaromatic features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Naratriptan has 63% oral bioavailability in men, providing another example of a basic indole/piperidine drug with F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Sertindole is well absorbed orally with a bioavailability of approximately 74%, supporting high F for a piperidine-containing heteroaromatic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Tasimelteon has an absolute bioavailability of 38% (90% CI 27-54%) in healthy volunteers, showing that even moderate-F analogues with similar lipophilic/aromatic character remain above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Risdiplam has high oral bioavailability due to almost complete absorption and negligible first-pass extraction, supporting high F for a complex heteroaromatic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Didanosine has an absolute oral bioavailability of 19% in children, below the threshold, but this low F is tied to its polar, acid-labile nucleoside structure and is not mechanistically transferable to the lipophilic fused heteroaromatic query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a small, lipophilic, basic fused heteroaromatic amine. Multiple high-transfer experimental analogues (niraparib, flecainide, naratriptan, sertindole, tasimelteon, risdiplam) show absolute oral bioavailability well above 20%, mostly 38-95%. The only low-F analogue, didanosine, is a polar acid-labile nucleoside whose poor absorption mechanism does not apply. Therefore predict high (F >= 20%).",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself.",
    "Most analogue F values come from different therapeutic classes; exact transporter and metabolic liabilities of the query are not directly measured.",
    "The didanosine low-F data are from a structurally dissimilar nucleoside and are not mechanistically transferable."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

